import{_ as i,a0 as a,w as p,s as u,ao as r,I as s,x as l,a1 as e,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"我最喜欢在 Linux 上玩的休闲游戏 | LCTT x X-CMD","titleTemplate":false,"description":"我最喜欢在 Linux 上玩的休闲游戏 | LCTT (202204) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我最喜欢在 Linux 上玩的休闲游戏 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我最喜欢在 Linux 上玩的休闲游戏 | LCTT (202204) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202204/20220226 My favorite casual games to play on Linux","title":"我最喜欢在 Linux 上玩的休闲游戏","tag":"202204","desc":""},"relativePath":"202204/20220226 My favorite casual games to play on Linux.md","filePath":"[post].md"}'),f={name:"202204/20220226 My favorite casual games to play on Linux.md"};function d(m,t,g,k,x,K){const o=a("Link");return p(),u("div",null,[t[24]||(t[24]=r('<h1 id="我最喜欢在-linux-上玩的休闲游戏" tabindex="-1">我最喜欢在 Linux 上玩的休闲游戏 <a class="header-anchor" href="#我最喜欢在-linux-上玩的休闲游戏" aria-label="Permalink to “我最喜欢在 Linux 上玩的休闲游戏”">​</a></h1><blockquote><p>在编译开源代码的同时在 Linux 上玩电子游戏。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202204/05/162045ecqsvd80cq2050dd.jpg" alt=""></p><p>我喜欢一款可以让自己沉浸数小时的好游戏，但我并不总是能够忽略工作而消失在电子游戏中。尽管如此，我还是喜欢不时的接受有趣的挑战，当我的计算机忙于做一些我需要等待的事情时，我最喜欢启动的两个应用程序是来自 KDE 游戏包的游戏：<strong>KBlocks</strong> 和 <strong>Kolf</strong>。</p><h3 id="kblocks" tabindex="-1">KBlocks <a class="header-anchor" href="#kblocks" aria-label="Permalink to “KBlocks”">​</a></h3><p>我最喜欢的电子游戏是这种从方块从天上掉下来，最好是落成一排，当方块相邻时就会神奇的消失的游戏。KBlocks 就是这样的，它的实现很棒。它可以使用<strong>左箭头</strong>和<strong>右箭头</strong>控制方块进行旋转，使用<strong>下箭头</strong>让方块更快的下落，使用<strong>空格键</strong>直接落下方块，不同的难度级别，方块下落的速度不同。</p><p><img src="https://opensource.com/sites/default/files/kblocks.jpg" alt="KBlocks" title="KBlocks"></p>',7)),s("p",null,[t[1]||(t[1]=l("（Seth Kenlon, ",-1)),e(o,{href:"https://creativecommons.org/licenses/by-sa/4.0/"},{default:n(()=>[...t[0]||(t[0]=[l("CC BY-SA 4.0",-1)])]),_:1}),t[2]||(t[2]=l("）",-1))]),t[25]||(t[25]=r('<p>KBlocks 的默认主题是古埃及，这对游戏的玩法没有影响，但对于古埃及的爱好者来说可能是愉快的游戏体验。不过，你可以在“<ruby>配置 KBlocks<rt>Configure KBlocks</rt></ruby>”菜单项中更改主题。有一个名为 “Plasma” 的替代主题，或者你可以单击“<ruby>获取新主题<rt>Get New Themes</rt></ruby>”按钮并下载由用户贡献的主题。</p><p><img src="https://opensource.com/sites/default/files/kblocks-invaders.jpg" alt="KBlocks Invaders by José Jorge" title="KBlocks Invaders by José Jorge"></p><p>(Seth Kenlon, CC BY-SA 4.0)</p><p>主题纯粹是美学方面的事情，但就艺术类型的人而言，为休闲游戏创建主题可能是为开源项目作出贡献的一种有趣方式。</p><h4 id="引导我进入-kde-plasma-桌面的游戏" tabindex="-1">引导我进入 KDE Plasma 桌面的游戏 <a class="header-anchor" href="#引导我进入-kde-plasma-桌面的游戏" aria-label="Permalink to “引导我进入 KDE Plasma 桌面的游戏”">​</a></h4><p>我承认，KBlocks 对我来说很难放下。事实上，正是我在会议期间玩游戏的愿望让我在 Emacs 中找到了 <code>M-x tetris</code> 命令，这反过来又让我发现并爱上了 Linux。这个游戏有很大的魅力。也许 KBlocks 将成为你发现 KDE Plasma 桌面的途径？</p><h3 id="kolf" tabindex="-1">Kolf <a class="header-anchor" href="#kolf" aria-label="Permalink to “Kolf”">​</a></h3><p>我不喜欢现实生活中的高尔夫，但在电脑上，迷你高尔夫结合了模拟物理和有趣的关卡设计，既令人愉快，又令人沮丧。Kolf 的目标如你所料：将高尔夫球打入洞中。当然，目的地总是在拐角处、需要越过山丘、经过池塘或者在墙后，因此你的目标是计算球速、摩擦力、坡度和轨迹，使其完美地让球回到球洞并尽可能少的击打球。</p><p><img src="https://opensource.com/sites/default/files/kolf.jpg" alt="Miniature golf" title="Miniature golf"></p>',9)),s("p",null,[t[4]||(t[4]=l("（Seth Kenlon, ",-1)),e(o,{href:"https://creativecommons.org/licenses/by-sa/4.0/"},{default:n(()=>[...t[3]||(t[3]=[l("CC BY-SA 4.0",-1)])]),_:1}),t[5]||(t[5]=l("）",-1))]),t[26]||(t[26]=s("p",null,"它从来没有看起来那么简单，而且我认为看着高尔夫球从物体上反弹，并滚下你从未打算让它靠近的山丘，这永远不会过时。",-1)),t[27]||(t[27]=s("h4",{id:"设计自己的球场",tabindex:"-1"},[l("设计自己的球场 "),s("a",{class:"header-anchor",href:"#设计自己的球场","aria-label":"Permalink to “设计自己的球场”"},"​")],-1)),t[28]||(t[28]=s("p",null,"当你尝试设计自己的迷你高尔夫球场时，乐趣才真正开始。是的，Kolf 有一个关卡编辑器，你可以在其中建造墙壁、放置池塘、山丘和沙坑，添加弹球式保险杠等等。",-1)),t[29]||(t[29]=s("p",null,[s("img",{src:"https://opensource.com/sites/default/files/kolf-edit.jpg",alt:"Kolf editor",title:"Kolf editor"})],-1)),s("p",null,[t[7]||(t[7]=l("（Seth Kenlon, ",-1)),e(o,{href:"https://creativecommons.org/licenses/by-sa/4.0/"},{default:n(()=>[...t[6]||(t[6]=[l("CC BY-SA 4.0",-1)])]),_:1}),t[8]||(t[8]=l("）",-1))]),t[30]||(t[30]=s("p",null,"因为 Kolf 可以是多人游戏，所以给每个玩家五分钟的时间来设计一个关卡，然后看看谁在谁的关卡上做的最好，这特别有趣。",-1)),t[31]||(t[31]=s("h3",{id:"linux-kde-游戏",tabindex:"-1"},[l("Linux KDE 游戏 "),s("a",{class:"header-anchor",href:"#linux-kde-游戏","aria-label":"Permalink to “Linux KDE 游戏”"},"​")],-1)),t[32]||(t[32]=s("p",null,"这绝不是 KDE 项目中仅有的两款游戏。还有许多其它游戏，包括卡牌游戏、拼图游戏和街机游戏。KDE 游戏包的好处是，它们包含了你可以随时走开的游戏，而且它们只需要你一点点的注意力。我在编译代码时使用这些游戏来消磨时间。有时候我并不能完整的玩完一局游戏，但我总是很欣赏这种心理状态的微妙转变。",-1)),t[33]||(t[33]=s("hr",null,null,-1)),s("p",null,[t[10]||(t[10]=l("via: ",-1)),e(o,{href:"https://opensource.com/article/22/2/casual-gaming-linux-kde"},{default:n(()=>[...t[9]||(t[9]=[l("https://opensource.com/article/22/2/casual-gaming-linux-kde",-1)])]),_:1})]),s("p",null,[t[15]||(t[15]=l("作者：",-1)),e(o,{href:"https://opensource.com/users/seth"},{default:n(()=>[...t[11]||(t[11]=[l("Seth Kenlon",-1)])]),_:1}),t[16]||(t[16]=l(" 选题：",-1)),e(o,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[12]||(t[12]=[l("lujun9972",-1)])]),_:1}),t[17]||(t[17]=l(" 译者：",-1)),e(o,{href:"https://github.com/perfiffer"},{default:n(()=>[...t[13]||(t[13]=[l("perfiffer",-1)])]),_:1}),t[18]||(t[18]=l(" 校对：",-1)),e(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[14]||(t[14]=[l("wxy",-1)])]),_:1})]),s("p",null,[t[21]||(t[21]=l("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[19]||(t[19]=[l("LCTT",-1)])]),_:1}),t[22]||(t[22]=l(" 原创编译，",-1)),e(o,{href:"https://linux.cn/"},{default:n(()=>[...t[20]||(t[20]=[l("Linux中国",-1)])]),_:1}),t[23]||(t[23]=l(" 荣誉推出",-1))])])}const L=i(f,[["render",d]]);export{C as __pageData,L as default};
